const resolveSolarOperationsFields = (
  incomingOperationsData: Record<string, unknown> = {},
  profile: Record<string, unknown> = {}
): Pick<
  OperationsDataFeed,
  'solarInstallationKw' | 'solarGenerationKwhPerMonth' | 'solarUsageKwhPerMonth' | 'solarNetMeteringEnabled' | 'renewableGenerationLocation' | 'renewablePpa'
> => {
  const manufacturingProfile = (profile.manufacturingProfile || {}) as Record<string, unknown>;
  const business = (profile.business || {}) as Record<string, unknown>;
  const solarPower = (business.solarPower || {}) as Record<string, unknown>;
  const operationsMetrics = ((profile.operations as Record<string, unknown> | undefined)?.metrics || {}) as Record<
    string,
    unknown
  >;

  const solarInstallationKw =
    Number(incomingOperationsData.solarInstallationKw) ||
    Number(operationsMetrics.solarInstallationKw) ||
    Number(manufacturingProfile.solarInstallationKw) ||
    Number(solarPower.installedCapacityKw) ||
    0;

  const hasOwn = (key: string) => Object.prototype.hasOwnProperty.call(incomingOperationsData, key);
  const solarGenerationKwhPerMonth = hasOwn('solarGenerationKwhPerMonth')
    ? Math.max(0, Number(incomingOperationsData.solarGenerationKwhPerMonth) || 0)
    : (
      Number(operationsMetrics.solarGenerationKwhPerMonth) ||
      Number(manufacturingProfile.solarGenerationKwhPerMonth) ||
      (Number(solarPower.annualGenerationKwh) > 0 ? Number(solarPower.annualGenerationKwh) / 12 : 0) ||
      0
    );

  const solarUsageKwhPerMonth = hasOwn('solarUsageKwhPerMonth')
    ? Math.max(0, Number(incomingOperationsData.solarUsageKwhPerMonth) || 0)
    : (
      (Number(solarPower.annualUsageKwh) > 0 ? Number(solarPower.annualUsageKwh) / 12 : 0) ||
      0
    );

  const solarNetMeteringEnabled = Boolean(
    incomingOperationsData.solarNetMeteringEnabled ?? solarPower.netMeteringEnabled
  );
  const renewableGenerationLocation = normalizeRenewableGenerationLocation(
    hasOwn('renewableGenerationLocation')
      ? incomingOperationsData.renewableGenerationLocation
      : solarPower.generationLocation
  ) as OperationsDataFeed['renewableGenerationLocation'];
  const rawRenewablePpa = hasOwn('renewablePpa')
    ? incomingOperationsData.renewablePpa
    : solarPower.renewablePpa;
  const renewablePpa = normalizeRenewablePpa(
    rawRenewablePpa && typeof rawRenewablePpa === 'object' ? rawRenewablePpa : undefined
  ) as RenewablePpaValue;

  return {
    solarInstallationKw,
    solarGenerationKwhPerMonth,
    solarUsageKwhPerMonth,
    solarNetMeteringEnabled,
    renewableGenerationLocation,
    renewablePpa
  };
};

